import{_ as s,o as p,c as e,a2 as t}from"./chunks/framework.EUByU7Iq.js";const d=JSON.parse('{"title":"桑柔","description":"","frontmatter":{"title":"桑柔","date":"2026-11-09T00:00:00.000Z","seq":23,"categories":["美文","诗经"],"collection":"《诗经 · 大雅》","tags":["诗经","先秦"],"poem":true,"author":"佚名","source_book":"诗经"},"headers":[],"relativePath":"blogs/诗经·大雅/桑柔.md","filePath":"blogs/诗经·大雅/桑柔.md"}'),o={name:"blogs/诗经·大雅/桑柔.md"};function c(l,a,n,m,r,_){return p(),e("div",null,[...a[0]||(a[0]=[t('<h1 id="桑柔" tabindex="-1">桑柔 <a class="header-anchor" href="#桑柔" aria-label="Permalink to &quot;桑柔&quot;">​</a></h1><p class="poem-meta">先秦 · 佚名　·　荡之什</p><div class="poem"><p class="poem-stanza">菀彼桑柔，其下侯旬，捋采其刘，瘼此下民。不殄心忧，仓兄填兮。倬彼昊天，宁不我矜？</p><p class="poem-stanza">四牡骙骙，旟旐有翩。乱生不夷，靡国不泯。民靡有黎，具祸以烬。于乎有哀，国步斯频。</p><p class="poem-stanza">国步灭资，天不我将。靡所止疑，云徂何往？君子实维，秉心无竞。谁生厉阶，至今为梗？</p><p class="poem-stanza">忧心殷殷，念我土宇。我生不辰，逢天僤怒。自西徂东，靡所定处。多我觏痻，孔棘我圉。</p><p class="poem-stanza">为谋为毖，乱况斯削。告尔忧恤，诲尔序爵。谁能执热，逝不以濯？其何能淑，载胥及溺。</p><p class="poem-stanza">如彼溯风，亦孔之僾。民有肃心，荓云不逮。好是稼穑，力民代食。稼穑维宝，代食维好？</p><p class="poem-stanza">天降丧乱，灭我立王。降此蟊贼，稼穑卒痒。哀恫中国，具赘卒荒。靡有旅力，以念穹苍。</p><p class="poem-stanza">维此惠君，民人所瞻。秉心宣犹，考慎其相。维彼不顺，自独俾臧。自有肺肠，俾民卒狂。</p><p class="poem-stanza">瞻彼中林，甡甡其鹿。朋友已谮，不胥以穀。人亦有言：进退维谷。</p><p class="poem-stanza">维此圣人，瞻言百里。维彼愚人，覆狂以喜。匪言不能，胡斯畏忌？</p><p class="poem-stanza">维此良人，弗求弗迪。维彼忍心，是顾是复。民之贪乱，宁为荼毒。</p><p class="poem-stanza">大风有隧，有空大谷。维此良人，作为式穀。维彼不顺，征以中垢。</p><p class="poem-stanza">大风有隧，贪人败类。听言则对，诵言如醉。匪用其良，复俾我悖。</p><p class="poem-stanza">嗟尔朋友，予岂不知而作。如彼飞虫，时亦弋获。既之阴女，反予来赫。</p><p class="poem-stanza">民之罔极，职凉善背。为民不利，如云不克。民之回遹，职竞用力。</p><p class="poem-stanza">民之未戾，职盗为寇。凉曰不可，覆背善詈。虽曰匪予，既作尔歌！</p></div>',3)])])}const z=s(o,[["render",c]]);export{d as __pageData,z as default};
